contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // Keep only a parameter precondition (no reads of c before the call that establishes state).
        require(_feeRate <= 5_000, "fee rate too high");

        bool reverted;
        address nftAfter;

        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
